CREATE TABLE dining_areas (id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL);
CREATE TABLE dining_tables (id INTEGER PRIMARY KEY, area_id INTEGER NOT NULL REFERENCES dining_areas(id), code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, seats INTEGER NOT NULL CHECK(seats > 0), status TEXT NOT NULL DEFAULT 'available');
CREATE TABLE menu_categories (id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE menu_items (id INTEGER PRIMARY KEY, sku TEXT NOT NULL UNIQUE, category_id INTEGER NOT NULL REFERENCES menu_categories(id), name TEXT NOT NULL, description TEXT NOT NULL, price REAL NOT NULL CHECK(price >= 0), active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE table_sessions (id INTEGER PRIMARY KEY, session_number TEXT NOT NULL UNIQUE, table_id INTEGER NOT NULL REFERENCES dining_tables(id), status TEXT NOT NULL, opened_at TEXT NOT NULL, closed_at TEXT);
CREATE UNIQUE INDEX one_active_session_per_table ON table_sessions(table_id) WHERE status='open';
CREATE TABLE restaurant_orders (id INTEGER PRIMARY KEY, order_number TEXT NOT NULL UNIQUE, session_id INTEGER NOT NULL REFERENCES table_sessions(id), status TEXT NOT NULL, subtotal REAL NOT NULL DEFAULT 0, total REAL NOT NULL DEFAULT 0, created_at TEXT NOT NULL, sent_at TEXT, served_at TEXT, paid_at TEXT, closed_at TEXT);
CREATE TABLE restaurant_order_lines (id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES restaurant_orders(id) ON DELETE CASCADE, menu_item_id INTEGER NOT NULL REFERENCES menu_items(id), item_name TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity > 0), unit_price REAL NOT NULL CHECK(unit_price >= 0), line_total REAL NOT NULL CHECK(line_total >= 0));
CREATE TABLE kitchen_tickets (id INTEGER PRIMARY KEY, ticket_number TEXT NOT NULL UNIQUE, order_id INTEGER NOT NULL UNIQUE REFERENCES restaurant_orders(id) ON DELETE CASCADE, status TEXT NOT NULL, station TEXT NOT NULL, created_at TEXT NOT NULL, started_at TEXT, ready_at TEXT, served_at TEXT);
CREATE TABLE payments (id INTEGER PRIMARY KEY, payment_number TEXT NOT NULL UNIQUE, order_id INTEGER NOT NULL UNIQUE REFERENCES restaurant_orders(id), amount REAL NOT NULL CHECK(amount > 0), method TEXT NOT NULL, status TEXT NOT NULL, paid_at TEXT NOT NULL);
CREATE TABLE receipts (id INTEGER PRIMARY KEY, receipt_number TEXT NOT NULL UNIQUE, order_id INTEGER NOT NULL UNIQUE REFERENCES restaurant_orders(id), total REAL NOT NULL, issued_at TEXT NOT NULL);
CREATE TABLE inventory (id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES menu_items(id), warehouse_id INTEGER NOT NULL, on_hand INTEGER NOT NULL CHECK(on_hand >= 0), reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved >= 0), updated_at TEXT NOT NULL, UNIQUE(product_id, warehouse_id));
